SELECT ${column} from t_practice_exam_paper_answer  where
deleted = 0 and practice_build_id = #{examPaperBuildId}

    and status = #{status}


    and passed = #{passed}

SELECT pepa.id,u.user_name userName ,u.real_name realName ,u.department_id departmentId ,u.id_card idCard,u.work_no workNo,u.job_title jobTitle,pepa.user_score userScore,pepa.paper_score paperScore,
pepa.question_correct questionCorrect,pepa.question_count questionCount,pepa.do_time doTime,pepa.status status,pepa.passed passed,pepa.create_time createTime
from t_user u JOIN t_practice_exam_paper_answer pepa on u.id = pepa.create_user and pepa.deleted = 0 and pepa.practice_build_id = #{id}
where  u.deleted= 0  and system_role = 1 and u.status = 1

    and u.user_name like concat('%',#{userName},'%')


    and  u.department_id in

        #{id}



    and pepa.status = #{status}


    and pepa.user_score >= #{minScore}


    and pepa.user_score <= #{maxScore}


    and pepa.create_user = #{dataFilterUserId}


    and pepa.create_department_id in

        #{item}
